def simulate_fixed_block(M, T):
    heights = [0] * M
    for t in range(1, T + 1):
        # Gardener targets the SAME 9 trees (a fixed 3x3 block)
        for i in range(M):
            heights[i] += 1
        # Lumberjack reduces the 4 tallest trees by 1
        tallest_idx = sorted(range(M), key=lambda i: heights[i], reverse=True)[:4]
        for i in tallest_idx:
            if heights[i] > 0:
                heights[i] -= 1
    return heights

