def simulate_many_blocks_improved(K, T):
    M = 9 * K
    heights = [0] * M
    for t in range(1, T + 1):
        # Gardener targets the block with the smallest sum of heights
        block_indices = []
        for i in range(K):
            block_indices.append(list(range(i*9, (i+1)*9)))

        best_block = None
        min_sum = float('inf')
        for block in block_indices:
            s = sum(heights[i] for i in block)
            if s < min_sum:
                min_sum = s
                best_block = block

        for i in best_block:
            heights[i] += 1

        # Lumberjack reduces 4 tallest trees.
        tallest_idx = sorted(range(M), key=lambda i: heights[i], reverse=True)[:4]
        for i in tallest_idx:
            if heights[i] > 0:
                heights[i] -= 1
    return heights

