def solve_for_K(K, target_H):
    # gardener wants to reach target_H for K trees.
    # This means they want to find the minimum T.
    M = 9 * K
    heights = [0] * M
    block_indices = []
    for i in range(K):
        block_indices.append(list(range(i*9, (i+1)*9)))

    for t in range(1, 1000000): # large enough T
        best_block = None
        min_sum = float('inf')
        for block in block_indices:
            s = sum(heights[i] for i in block)
            if s < min_sum:
                min_sum = s
                best_block = block
        for i in best_block:
            heights[i] += 1
        tallest_idx = sorted(range(M), key=lambda i: heights[i], reverse=True)[:4]
        for i in tallest_idx:
            if heights[i] > 0:
                heights[i] -= 1

        if sum(1 for h in heights if h >= target_H) >= K:
            return t
    return -1

