def simulate_with_ids(K, turns=5000):
    heights = [0] * K
    ids = list(range(K))
    for t in range(turns):
        combined = sorted(zip(heights, ids))
        sorted_heights = [h for h, i in combined]
        sorted_ids = [i for h, i in combined]

        gardener_indices = sorted_ids[:min(9, K)]
        for i in range(K):
            if ids[i] in gardener_indices:
                heights[i] += 1

        remaining_indices = [i for i in range(K) if ids[i] not in gardener_indices]
        remaining_indices.sort(key=lambda i: (heights[i], i))

        lumberjack_indices = remaining_indices[:4]
        for i in lumberjack_indices:
            if heights[i] > 0:
                heights[i] -= 1

    return min(heights)

