def solve():
    M = 2025
    # Let's consider the board as a grid of size M x M.
    # A 3x3 block is identified by its top-left corner (r, c).
    # The possible top-left corners are (r, c) where 1 <= r, c <= M-2.
    # Let B be the set of all such 3x3 blocks.
    # For each tree at (x, y) where 1 <= x, y <= M,
    # let c(x, y) be the number of blocks in B that contain (x, y).
    # A block with top-left corner (r, c) contains (x, y) iff:
    # r <= x <= r+2 and c <= y <= c+2
    # which is x-2 <= r <= x and y-2 <= c <= y.
    # Since 1 <= r, c <= M-2, the number of such (r, c) is:
    # count of r in [max(1, x-2), min(M-2, x)]
    # count of c in [max(1, y-2), min(M-2, y)]

    # Let S be the set of trees (x, y) such that c(x, y) >= 5.
    # We want to check if sum_{b in B} |S \cap b| > 4 * |B|.

    # Let's test this for small M.
    for M_small in range(3, 11):
        blocks = []
        for r in range(1, M_small - 1):
            for c in range(1, M_small - 1):
                blocks.append((r, c))

        m = len(blocks)
        S = []
        # c_count[x][y] is the number of blocks in B containing tree (x, y)
        c_count = [[0] * (M_small + 1) for _ in range(M_small + 1)]
        for r, c in blocks:
            for x in range(r, r + 3):
                for y in range(c, c + 3):
                    c_count[x][y] += 1

        for x in range(1, M_small + 1):
            for y in range(1, M_small + 1):
                if c_count[x][y] >= 5:
                    S.append((x, y))

        K = len(S)

        # Now calculate sum_{b in B} |S \cap b|
        total_S_in_blocks = 0
        for r, c in blocks:
            count = 0
            for x in range(r, r + 3):
                for y in range(c, c + 3):
                    if (x, y) in S:
                        count += 1
            total_S_in_blocks += count

        print(f"M={M_small}, K={K}, sum={total_S_in_blocks}, m={m}, sum > 4m: {total_S_in_blocks > 4*m}")

solve()

def simulate(K, turns=1000):
    h = [0] * K
    for _ in range(turns):
        # Gardener's turn: increase 9 smallest
        indices = sorted(range(K), key=lambda i: h[i])
        for i in indices[:9]:
            h[i] += 1

        # Lumberjack's turn: decrease 4 largest positive
        pos_indices = [i for i in range(K) if h[i] > 0]
        pos_indices.sort(key=lambda i: h[i], reverse=True)
        for i in range(min(4, len(pos_indices))):
            h[pos_indices[i]] -= 1
    return h

for K in range(1, 12):
    res = simulate(K)
    print(f"K={K}: {res}")

